const R=wb.getWorksheet('RANGES'), L=wb.getWorksheet('LISTS');
const ser=(v)=>{ if(typeof v==='number') return v; const m=String(v).trim().match(/^(\d+)\/(\d+)\/(\d+)$/); return Math.round((Date.UTC(+m[3],+m[1]-1,+m[2])-Date.UTC(1899,11,30))/86400000); };
const agg=(a)=>{const m=new Map(); for(const r of R.getRange(a).getValues()){const k=ser(r[0])+'|'+r[2]; m.set(k,(m.get(k)||0)+r[3]);}
 return [...m].map(([k,v])=>{const [d,c]=k.split('|');return [+d,c,v]}).sort((x,y)=>x[0]-y[0]||(x[1]<y[1]?-1:x[1]>y[1]?1:0));};
const chk=agg('B3:E13');
const data=agg('B18:E32'), op=agg('B37:E55');
L.getRange('B15:D19').setValues(data);
L.getRange('B25:D31').setValues(op);
L.getRange('D20').setValue('=SUM(D15:D19)');
L.getRange('D32').setValue('=SUM(D25:D31)');
log(JSON.stringify(chk));
L.getRange('A1:D32').getValues().map((r,i)=>(i+1)+'|'+r.join('|')).join('\n')+'\n'+['B15','B19','B31','D15','D20','D32'].map(a=>a+'='+L.getRange(a).getText()+' '+L.getRange(a).getStyle().getNumberFormat()).join('\n')

